'use strict';
(()=>{
const M=window.NutriCalendar,$=id=>document.getElementById(id),params=new URLSearchParams(location.search),labels={diet:'饮食',health:'身体感受',question:'待问问题'};
const legacyLabel=document.querySelector('.nutri-demo-label span');if(legacyLabel)legacyLabel.textContent='旧版独立本机记录 · 不与 v3 合成账号互通';
const today=()=>M.dateKey(new Date());let selected=M.validDate(params.get('date'))?params.get('date'):today(),period='daily',filter='all',state=M.empty(),mealEntries=[],mealWarning='',editing=null,undo=null,dirty=false,loaded=false;
let storage;try{storage=window.localStorage;}catch{storage={getItem(){throw Error('Storage unavailable');},setItem(){throw Error('Storage unavailable');}};}
const repo=M.repository(storage),text=(id,value)=>{$(id).textContent=value;};
function node(tag,className,value){const el=document.createElement(tag);if(className)el.className=className;if(value!==undefined)el.textContent=value;return el;}
function allRecords(){return state.records.concat(mealEntries);}
function loadMeals(){mealEntries=[];mealWarning='';if(window.NutriDiet?.calendarEntries){try{const result=window.NutriDiet.calendarEntries(storage);if(result.ok)mealEntries=result.entries;else mealWarning=result.message||'饮食记录暂时无法读取。';}catch{mealWarning='饮食记录暂时无法读取；报告未计入这些记录。';}}else mealWarning='饮食日记录尚未加载，报告暂只包含本页手动记录。';text('meal-status',mealWarning);}
function reload(){const result=repo.load();state=result.state;loaded=result.ok;text('storage-status',result.ok?'':result.message);loadMeals();render();}
function setDate(value){if(!M.validDate(value)){text('storage-status','请选择 1900—2199 年内的有效日期。');$('selected-date').value=selected;return;}selected=value;render();}
function renderCalendar(){const days=M.monthDays(selected),[year,month]=selected.split('-');text('month-heading',`${year} 年 ${Number(month)} 月`);$('selected-date').value=selected;$('prev-month').disabled=selected.startsWith('1900-01');$('next-month').disabled=selected.startsWith('2199-12');const host=$('calendar-days');host.replaceChildren();const weekday=(new Date(`${days[0]}T12:00:00Z`).getUTCDay()+6)%7;for(let i=0;i<weekday;i++)host.append(node('span'));const records=allRecords(),marked=new Set(records.map(r=>r.date));for(const date of days){const b=node('button','',String(Number(date.slice(-2))));b.type='button';b.dataset.date=date;b.dataset.today=String(date===today());b.dataset.recorded=String(marked.has(date));b.setAttribute('aria-pressed',String(date===selected));if(date===today())b.setAttribute('aria-current','date');b.setAttribute('aria-label',`${date}${marked.has(date)?'，有记录':'，暂无记录'}`);b.addEventListener('click',()=>setDate(date));host.append(b);}const summary=M.summarize(records,days);text('month-coverage',`本月已记录 ${summary.recordedDays} 天，共 ${summary.total} 条。未记录的日期不作健康推断。`);}
function renderReport(){const dates=period==='daily'?[selected]:M.weekDates(selected),summary=M.summarize(allRecords(),dates);for(const name of ['daily','weekly']){const tab=$(name+'-tab'),active=name===period;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;}$('report-panel').setAttribute('aria-labelledby',period+'-tab');text('report-title',period==='daily'?`${selected} 日报`:`${dates[0]} 至 ${dates[6]} 周报`);text('report-coverage',summary.total?`共 ${summary.total} 条记录 · ${summary.recordedDays}/${dates.length} 天有记录${period==='weekly'?` · ${summary.missingDays} 天无记录（非零摄入）`:''}`:'还没有记录。保存饮食、身体感受或待问问题后，这里才会形成报告。');const counts=$('report-counts');counts.replaceChildren();for(const type of M.TYPES){const el=node('div');el.append(node('strong','',String(summary.counts[type])),node('span','',labels[type]));counts.append(el);}let nutrition=summary.counts.diet===0?'暂无饮食记录，无法汇总热量。':summary.kcalEstimate===null?`饮食 ${summary.counts.diet} 条，热量均未知；未按 0 计算。`:`已知部分估算合计 ${summary.kcalEstimate} 千卡；${summary.knownDietCount} 条饮食有已知数值，${summary.unknownDietCount} 条完全未知。`;const partial=summary.records.filter(r=>r.source==='local-meal'&&r.unknownItemCount>0).length;if(partial)nutrition+=` 其中 ${partial} 餐含未知食材，合计不完整。`;nutrition+=' 这些是手动值或食材估算，不是测量结果，也不代表完整摄入。';text('nutrition-summary',nutrition);const weeks=$('week-overview');weeks.replaceChildren();if(period==='weekly')for(const date of dates){const count=summary.records.filter(r=>r.date===date).length,row=node('div','week-row');row.append(node('span','',date),node('span','',count?`${count} 条记录`:'无记录'));weeks.append(row);}const details=$('weekly-details');details.replaceChildren();if(period==='weekly')for(const type of M.TYPES){const list=summary.records.filter(r=>r.type===type);if(!list.length)continue;const group=node('details','weekly-detail');group.append(node('summary','',`查看本周${labels[type]}（${list.length} 条）`));for(const r of list){const item=node('div','weekly-note');item.append(node('strong','',`${r.date} ${r.time}`),node('p','entry-text',r.text));if(type==='question')item.append(node('p','subtle','未发送 · 未获专业答复'));group.append(item);}details.append(group);}}
function renderEntries(){text('entry-date',`${selected} · 按当地记录时间排序`);document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===filter)));const rows=M.summarize(allRecords(),[selected]).records.filter(r=>filter==='all'||r.type===filter),host=$('entries');host.replaceChildren();if(!rows.length){const p=node('div','empty');p.append(node('strong','',filter==='all'?'这一天还没有记录':`这一天还没有${labels[filter]}记录`),node('span','','点“记一笔”，从一件小事开始。'));host.append(p);}for(const r of rows){const article=node('article','entry');article.append(node('h3','',`${r.time} · ${labels[r.type]}`),node('p','entry-meta',`${r.source==='local-meal'?'本机饮食日记录 · 已确认实吃':r.source==='local-guide'?'本机引导摘要 · 用户确认保存':r.source==='local-assessment'?'自填资料摘要 · 非诊断':'手动记录'} · ${r.timeZone||'未记录时区'}`),node('p','entry-text',r.text));if(r.type==='question')article.append(node('p','subtle','未发送 · 未获专业答复，仅作为待问备忘'));if(r.type==='diet')article.append(node('p','subtle',r.kcal===null?'热量未知':`已知部分估算 ${r.kcal} 千卡（非测量值）`));if(r.nutritionNote)article.append(node('p','subtle',r.nutritionNote));const actions=node('div','entry-actions');if(r.source==='local-meal'){const link=node('a','','去旧版饮食日查看 / 编辑');link.href='diet.html?legacy=1&date='+encodeURIComponent(r.date)+'&slot='+encodeURIComponent(r.slot||'lunch');actions.append(link);}else{const edit=node('button','','编辑'),del=node('button','','删除');edit.type=del.type='button';edit.setAttribute('aria-label',`编辑 ${r.time} 的${labels[r.type]}记录`);del.setAttribute('aria-label',`删除 ${r.time} 的${labels[r.type]}记录`);edit.addEventListener('click',()=>openEditor(r));del.addEventListener('click',()=>remove(r));actions.append(edit,del);}article.append(actions);host.append(article);}$('undo-box').hidden=!undo;}
function syncLegacyNavigation(){for(const link of document.querySelectorAll('[data-shell-nav] a,.bottom-nav a')){if(!link.href)continue;const page=new URL(link.href,location.href).pathname.split('/').pop();if(!['diet.html','health-calendar.html'].includes(page))continue;const query=new URLSearchParams({legacy:'1',date:selected});if(window.NutriDiet?.SLOTS?.includes(params.get('slot')))query.set('slot',params.get('slot'));link.href=page+'?'+query.toString();link.setAttribute('aria-label',page==='diet.html'?'旧版本机饮食记录':'旧版本机日历');}}
document.addEventListener?.('DOMContentLoaded',syncLegacyNavigation,{once:true});
function render(){syncLegacyNavigation();renderCalendar();renderReport();renderEntries();$('add-entry').disabled=!loaded;}
function editorType(){const type=$('entry-type').value;$('kcal-field').hidden=type!=='diet';$('question-note').hidden=type!=='question';$('entry-text').placeholder={diet:'例如：午餐吃了什么、大约多少',health:'例如：今天的身体感受、睡眠或活动情况',question:'写下准备向专业人士询问的问题'}[type];}
function openEditor(record=null,type='diet'){if(dirty&&!window.confirm('放弃尚未保存的输入，打开另一条记录？'))return;editing=record?.id||null;dirty=false;$('editor-section').hidden=false;text('editor-heading',record?'编辑记录':'记一笔');$('entry-type').value=record?.type||type;$('entry-day').value=record?.date||selected;const now=new Date();$('entry-time').value=record?.time||`${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`;$('entry-text').value=record?.text||'';$('entry-kcal').value=record?.kcal??'';$('local-consent').checked=false;const original=record?.timeZone||M.zone();$('entry-zone').dataset.zone=original;text('entry-zone',`记录归属时区：${original}。补记按你选择的日期和当地时间归档。`);text('form-status','');editorType();$('editor-section').scrollIntoView({block:'start',behavior:'auto'});$('entry-type').focus();}
function closeEditor(){if(dirty&&!window.confirm('输入尚未保存，确定取消？'))return;$('editor-section').hidden=true;editing=null;dirty=false;$('add-entry').focus();}
function save(records){const result=repo.commit(records);loadMeals();if(!result.ok){text('storage-status',result.message);render();return false;}state=result.state;text('storage-status','已保存到当前浏览器。未上传。');return true;}
$('entry-form').addEventListener('input',()=>dirty=true);$('entry-type').addEventListener('change',editorType);$('entry-form').addEventListener('submit',e=>{e.preventDefault();if(!$('local-consent').checked){text('form-status','请先确认本机保存说明。');return;}const previous=state.records.find(r=>r.id===editing),now=Date.now();let record;try{record=M.normalize({id:editing||'manual-'+now+'-'+Math.random().toString(36).slice(2),date:$('entry-day').value,time:$('entry-time').value,type:$('entry-type').value,text:$('entry-text').value,kcal:$('entry-kcal').value,source:previous?.source==='local-guide'&&$('entry-type').value==='question'?'local-guide':previous?.source==='local-assessment'&&$('entry-type').value==='health'?'local-assessment':'manual',timeZone:$('entry-zone').dataset.zone,createdAt:previous?.createdAt||now,updatedAt:now});}catch(err){text('form-status',err.message);return;}const next=state.records.filter(r=>r.id!==record.id).concat(record);if(!save(next)){text('form-status',$('storage-status').textContent);return;}selected=record.date;dirty=false;editing=null;$('editor-section').hidden=true;render();$('add-entry').focus();});
function remove(record){if(!window.confirm('删除这条本机记录？离开或刷新页面前可撤销。'))return;if(save(state.records.filter(r=>r.id!==record.id))){undo=record;render();$('undo-delete').focus();}}
$('undo-delete').addEventListener('click',()=>{if(!undo)return;if(state.records.some(r=>r.id===undo.id)){text('storage-status','这条记录已存在，无需重复恢复。');return;}if(save(state.records.concat(undo))){selected=undo.date;undo=null;render();}});
$('add-entry').addEventListener('click',()=>openEditor());$('cancel-edit').addEventListener('click',closeEditor);$('prev-month').addEventListener('click',()=>setDate(M.shiftMonth(selected,-1)));$('next-month').addEventListener('click',()=>setDate(M.shiftMonth(selected,1)));$('today').addEventListener('click',()=>setDate(today()));$('selected-date').addEventListener('change',e=>setDate(e.target.value));
for(const name of ['daily','weekly'])$(name+'-tab').addEventListener('click',()=>{period=name;renderReport();});document.querySelector('[role="tablist"]').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();period=e.key==='Home'?'daily':e.key==='End'?'weekly':period==='daily'?'weekly':'daily';renderReport();$(period+'-tab').focus();});document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;renderEntries();}));
function large(on){document.body.classList.toggle('large-mode',on);$('large-toggle').setAttribute('aria-pressed',String(on));$('back-link').href='../nutrition-booklet.html'+(on?'?large=1':'');}$('large-toggle').addEventListener('click',()=>large(!document.body.classList.contains('large-mode')));large(params.get('large')==='1');
window.addEventListener('storage',e=>{
// Meals are an independent, read-only projection: refreshing them must not reset a calendar draft or its conflict snapshot.
if(e.key==='ai-nutri-diet-v1'){loadMeals();render();return;}
if(e.key===M.KEY||e.key===null){if(dirty){loadMeals();render();text('storage-status','另一个页面更改了本机记录。请保留当前输入；重新打开此页可读取最新记录。');}else{undo=null;editing=null;$('editor-section').hidden=true;reload();}}
});window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
text('timezone-note',`当前设备时区：${M.zone()}。周报按周一至周日；历史日期保留录入时的归属，不因旅行自动改日。`);reload();if(loaded&&M.TYPES.includes(params.get('type')))openEditor(null,params.get('type'));
})();
